mapper.select:
SELECT ROOM_ID, USER_ID, ADMIN_ID, STATUS, CREATED_AT, CLOSED_AT
FROM CHAT_ROOMS
WHERE ROOM_ID = #{roomId}

SELECT MESSAGE_ID, ROOM_ID, SENDER_ID, CONTENT, IS_READ, CREATED_AT
FROM CHAT_MESSAGES
WHERE MESSAGE_ID = #{messageId}

mapper.update:
UPDATE CHAT_MESSAGES
SET IS_READ = TRUE
WHERE ROOM_ID = #{roomId}
  AND SENDER_ID != #{readerId}
  AND IS_READ = FALSE

mapper.select:
SELECT COUNT(*)
FROM CHAT_MESSAGES
WHERE ROOM_ID = #{roomId}
  AND SENDER_ID != #{readerId}
  AND IS_READ = FALSE

mapper.update:
UPDATE CHAT_ROOMS
SET STATUS = 'CLOSED', CLOSED_AT = CURRENT_TIMESTAMP
WHERE ROOM_ID = #{roomId}
  AND ADMIN_ID = #{adminId}
  AND STATUS = 'IN_PROGRESS'
